#!/usr/bin/env python3
"""Validate and safely extract the ShelfSense source archive."""
from __future__ import annotations

import argparse
import shutil
import stat
import zipfile
from pathlib import Path, PurePosixPath

MAX_FILES = 500
MAX_TOTAL_BYTES = 100 * 1024 * 1024
MAX_FILE_BYTES = 20 * 1024 * 1024
MAX_RATIO = 1000
EXPECTED_FILES = {
    "shelfsense/pyproject.toml",
    "shelfsense/src/shelfsense/__init__.py",
    "shelfsense/data/sales.csv",
    "shelfsense/data/inventory.csv",
}

class UnsafeArchiveError(ValueError):
    pass

def _validated_entries(archive: zipfile.ZipFile) -> list[tuple[zipfile.ZipInfo, PurePosixPath]]:
    infos = archive.infolist()
    if len(infos) > MAX_FILES:
        raise UnsafeArchiveError(f"Archive has too many entries: {len(infos)}")
    if archive.testzip() is not None:
        raise UnsafeArchiveError("ZIP CRC validation failed")

    seen: set[str] = set()
    total = 0
    validated = []
    found: set[str] = set()

    for info in infos:
        raw = info.filename
        if not raw or "\x00" in raw or "\\" in raw:
            raise UnsafeArchiveError(f"Invalid archive path: {raw!r}")
        path = PurePosixPath(raw)
        if path.is_absolute() or ".." in path.parts or not path.parts:
            raise UnsafeArchiveError(f"Path traversal or absolute path: {raw!r}")
        if ":" in path.parts[0] or path.parts[0] != "shelfsense":
            raise UnsafeArchiveError(f"Unexpected archive root: {raw!r}")

        normalized = path.as_posix().rstrip("/")
        key = normalized.casefold()
        if key in seen:
            raise UnsafeArchiveError(f"Duplicate or case-colliding path: {raw!r}")
        seen.add(key)

        mode = (info.external_attr >> 16) & 0xFFFF
        if stat.S_ISLNK(mode):
            raise UnsafeArchiveError(f"Symbolic links are not allowed: {raw!r}")
        if info.flag_bits & 0x1:
            raise UnsafeArchiveError(f"Encrypted ZIP entry is not allowed: {raw!r}")

        parts = {part.casefold() for part in path.parts}
        filename = path.name.casefold()
        suffix = path.suffix.casefold()
        if parts.intersection({".git", ".venv", "venv", "__pycache__"}):
            raise UnsafeArchiveError(f"Generated or repository metadata is not allowed: {raw!r}")
        if filename == ".env" or filename.startswith(".env."):
            raise UnsafeArchiveError(f"Environment secret file is not allowed: {raw!r}")
        if suffix in {".pem", ".key", ".p12", ".pfx", ".pyc", ".db"}:
            raise UnsafeArchiveError(f"Sensitive or generated file is not allowed: {raw!r}")
        if suffix == ".sqlite" and normalized != "shelfsense/demo-output/shelfsense.sqlite":
            raise UnsafeArchiveError(f"Unexpected database file: {raw!r}")

        if not info.is_dir():
            if info.file_size > MAX_FILE_BYTES:
                raise UnsafeArchiveError(f"File is too large: {raw!r}")
            total += info.file_size
            if total > MAX_TOTAL_BYTES:
                raise UnsafeArchiveError("Archive expands beyond the configured size limit")
            if info.file_size > 1024 * 1024 and info.compress_size and info.file_size / info.compress_size > MAX_RATIO:
                raise UnsafeArchiveError(f"Suspicious compression ratio: {raw!r}")
            found.add(normalized)

        validated.append((info, path))

    missing = EXPECTED_FILES - found
    if missing:
        raise UnsafeArchiveError(f"Archive is missing required project files: {sorted(missing)}")
    return validated

def validate_and_extract(archive_path: Path, destination: Path) -> int:
    destination = destination.resolve()
    if destination.exists():
        raise UnsafeArchiveError(f"Destination already exists: {destination}")
    destination.mkdir(parents=True)

    try:
        with zipfile.ZipFile(archive_path) as archive:
            entries = _validated_entries(archive)
            extracted = 0
            for info, relative in entries:
                # The prebuilt demo database is regenerated by CI and is not committed.
                if relative.as_posix() == "shelfsense/demo-output/shelfsense.sqlite":
                    continue
                target = destination.joinpath(*relative.parts)
                if info.is_dir():
                    target.mkdir(parents=True, exist_ok=True)
                    continue
                target.parent.mkdir(parents=True, exist_ok=True)
                with archive.open(info, "r") as source, target.open("xb") as output:
                    shutil.copyfileobj(source, output)
                extracted += 1
            return extracted
    except (zipfile.BadZipFile, OSError, RuntimeError) as exc:
        shutil.rmtree(destination, ignore_errors=True)
        raise UnsafeArchiveError(f"Could not safely extract archive: {exc}") from exc
    except Exception:
        shutil.rmtree(destination, ignore_errors=True)
        raise

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("archive", type=Path)
    parser.add_argument("destination", type=Path)
    args = parser.parse_args()
    count = validate_and_extract(args.archive, args.destination)
    print(f"Validated and safely extracted {count} files to {args.destination}")

if __name__ == "__main__":
    main()
